package cn.jingyu.deepseek.test;
import cn.jingyu.deepseek.*;import cn.jingyu.deepseek.NativeActivity;import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import org.json.*;import java.io.*;import java.lang.reflect.*;import java.util.concurrent.atomic.*;
/** Real Flash integration, synthetic memories only. External key is never included in this file. */
public final class RealMemorySmokeTest extends Instrumentation {
 private NativeActivity activity;private final StringBuilder report=new StringBuilder();
 public void onCreate(Bundle b){super.onCreate(b);start();}private void main(Runnable r){runOnMainSync(r);waitForIdleSync();}private Object field(String name)throws Exception{Field f=NativeActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(activity);}private JSONObject state()throws Exception{return (JSONObject)field("state");}private ChatSession session()throws Exception{return (ChatSession)field("session");}private MemoryBook memory()throws Exception{Field f=ChatSession.class.getDeclaredField("memory");f.setAccessible(true);return (MemoryBook)f.get(session());}private JSONObject chat()throws Exception{JSONArray chats=state().getJSONArray("chats");String id=state().optString("current");for(int i=0;i<chats.length();i++)if(chats.getJSONObject(i).optString("id").equals(id))return chats.getJSONObject(i);throw new AssertionError("No current chat");}private JSONObject last()throws Exception{JSONArray m=chat().getJSONArray("messages");return m.getJSONObject(m.length()-1);}private void invoke(String name){try{Method m=NativeActivity.class.getDeclaredMethod(name);m.setAccessible(true);m.invoke(activity);}catch(Exception e){throw new RuntimeException(e);}}private void check(boolean ok,String label){if(!ok)throw new AssertionError(label);report.append("PASS ").append(label).append('\n');}private void done()throws Exception{long due=SystemClock.uptimeMillis()+180000;while(SystemClock.uptimeMillis()<due){AtomicBoolean busy=new AtomicBoolean(true);main(()->{try{busy.set((Boolean)field("busy"));}catch(Exception e){throw new RuntimeException(e);}});if(!busy.get())return;SystemClock.sleep(200);}throw new AssertionError("Real request exceeded 180 seconds");}private void send(String s)throws Exception{main(()->{try{((EditText)field("input")).setText(s);((Button)field("send")).performClick();}catch(Exception e){throw new RuntimeException(e);}});done();check(last().optString("status").equals("complete"),"real memory-aware turn completes");}private void fresh(){main(()->invoke("startNew"));}
 public void onStart(){Bundle result=new Bundle();LocalStore store=new LocalStore(getTargetContext());try{File file=new File(getTargetContext().getFilesDir(),"test-key.txt");String key;try(InputStream in=new FileInputStream(file);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);key=out.toString("UTF-8").trim();}file.delete();store.key(key);key=null;MemoryBook book=new MemoryBook(getTargetContext());book.clear();book.automatic(false);store.save(new JSONObject().put("chats",new JSONArray()).put("streaming",true).put("effort","off").put("autoSummary",true).toString());activity=(NativeActivity)startActivitySync(new Intent(getTargetContext(),NativeActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();
 send("请记住：我的测试昵称是青柚，我学习自动化专业。只保存这两项用于后续测试。");check(memory().count()>0&&last().optJSONArray("memoryEvents")!=null,"real Flash calls remember_memory with valid current-message evidence");fresh();send("请根据你已有的记忆，告诉我该怎么称呼我、我学什么专业。只用一句话回答。");String recalled=last().optString("text");check(recalled.contains("青柚")&&recalled.contains("自动化"),"new conversation retrieves the saved synthetic profile");
 main(()->{try{state().put("system","默认使用中文并详细解释。");}catch(Exception e){throw new RuntimeException(e);}});fresh();send("本条要求优先：只输出一个JSON对象，不要代码围栏或解释，键为answer，值为数字2。题目：1+1。");check(new JSONObject(last().getString("text").trim()).getInt("answer")==2,"enhanced prompt follows current output format over saved defaults");fresh();send("不用联网或工具：电阻R=120Ω，电压U=12V，求电流。只给一个含单位的等式。");String math=last().optString("text");check(math.contains("0.1")&&math.contains("A"),"enhanced prompt preserves numeric result and physical unit");
 fresh();send("请忘记我之前保存的所有测试昵称和自动化专业的记忆，删除这些已保存条目。");check(memory().count()==0,"real Flash finds and explicitly forgets all requested synthetic memories");
 JSONArray messages=new JSONArray();for(int i=0;i<12;i++)messages.put(new JSONObject().put("id","real-summary-"+i).put("role",i%2==0?"user":"assistant").put("status","complete").put("text",i==0?"项目初始K=7，电阻120Ω，不考虑二战方案。":i==4?"更正：最终K=9，其余不变。":"继续控制系统项目，保留单位与必要推导。"));JSONObject longChat=new JSONObject().put("id","real-summary").put("title","Synthetic summary").put("messages",messages);main(()->{try{state().put("chats",new JSONArray().put(longChat));state().put("current","real-summary");session().organize(longChat);}catch(Exception e){throw new RuntimeException(e);}});done();check(ContextSummary.covered(longChat)>0&&messages.length()==12,"real summary request preserves all originals");String summary=longChat.getJSONObject("summary").getString("text");check(summary.contains("9")&&summary.contains("120")&&summary.contains("不考虑"),"real summary retains correction, number and negative constraint");result.putString("report",report.toString());finish(Activity.RESULT_OK,result);
 }catch(Throwable e){result.putString("report",report+"FAIL "+e);finish(Activity.RESULT_CANCELED,result);}finally{try{store.key("");new File(getTargetContext().getFilesDir(),"test-key.txt").delete();new MemoryBook(getTargetContext()).clear();}catch(Exception ignored){}}}
}
